"""Extract production surface upload/unlock and layout code for native tests."""
import argparse
import re
from pathlib import Path


def function(text, signature):
    if text.count(signature) != 1:
        raise ValueError(f"Expected one function: {signature}")
    start = text.index(signature)
    return text[start:text.index("\n}\n", start) + 3]


def prepare(source, output, copy_reference=False, negative_control=False):
    client = source / "bridge/src/client"
    util = source / "bridge/src/util"
    text = (client / "d3d9_surface.cpp").read_text(encoding="utf-8")
    notices = text[:text.index('#include "pch.h"')]
    methods = "\n".join(function(text, signature) for signature in (
        "void Direct3DSurface9_LSS::unlock()",
        "void Direct3DSurface9_LSS::sendDataToServer(",
        "std::tuple<size_t, size_t> Direct3DSurface9_LSS::getRectDimensions("))
    start_marker = "        // NV-DXVK start: Copy only complete, tightly packed surfaces in one pass."
    end_marker = "        // NV-DXVK end"
    if methods.count(start_marker) != 1:
        raise ValueError("Surface copy path changed; update the test extraction")
    start = methods.index(start_marker)
    end = methods.index(end_marker, start) + len(end_marker)
    if copy_reference:
        # Restore only the previous copy loop; transport and layout are identical.
        methods = methods[:start] + """        FOR_EACH_RECT_ROW(lockInfo.lockedRect, height, m_desc.Format, {
          memcpy(blobPacketPtr, ptr, rowSize);
          blobPacketPtr += rowSize;
        });""" + methods[end:]
        methods = "#define SURFACE_ROW_REFERENCE 1\n" + methods
    elif negative_control:
        needle = "lockInfo.lockedRect.Pitch > 0 && static_cast<size_t>(lockInfo.lockedRect.Pitch) == rowSize"
        if methods.count(needle) != 1:
            raise ValueError("Cannot create the missing-pitch-check negative control")
        methods = methods.replace(needle, "true")
    header = (client / "d3d9_surface.h").read_text(encoding="utf-8")
    begin, end = "  struct LockInfo {", "  std::queue<LockInfo> m_lockInfoQueue;"
    if header.count(begin) != 1 or header.count(end) != 1:
        raise ValueError("Surface lock storage changed; update the test harness")
    storage = header[header.index(begin):header.index(end) + len(end)]
    helpers = (util / "util_texture_and_volume.h").read_text(encoding="utf-8")
    for include in ('#include "util_bridgecommand.h"', '#include "util_common.h"'):
        if helpers.count(include) != 1:
            raise ValueError("Surface format helper dependencies changed")
        helpers = helpers.replace(include, "")
    common = (util / "util_common.h").read_text(encoding="utf-8")
    pitches = re.findall(r"^  static const uint32_t MinSurfacePitch = [^;]+;", common, re.MULTILINE)
    if len(pitches) != 1:
        raise ValueError("Surface minimum pitch changed")
    helpers = "namespace caps {\n" + pitches[0] + "\n}\n" + helpers
    output.mkdir(parents=True, exist_ok=True)
    for name, contents in (("surface_methods.h", methods), ("surface_lock_storage.h", storage),
                           ("surface_format.h", helpers)):
        (output / name).write_text(notices + contents + "\n", encoding="utf-8", newline="\n")


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("source", type=Path)
    parser.add_argument("output", type=Path)
    control = parser.add_mutually_exclusive_group()
    control.add_argument("--copy-reference", action="store_true")
    control.add_argument("--negative-control", action="store_true")
    args = parser.parse_args()
    prepare(args.source, args.output, args.copy_reference, args.negative_control)
